SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, CASE WHEN temp_c >= 39.2 THEN 'LARGE' ELSE 'SMALL' END AS temp_c_tier, device_code, COUNT(*) FILTER (WHERE device_code = 'DV-04') AS dv_04_rows, BIT_AND(status_bits) AS status_bits_bit_and, MIN(temp_c) AS min_temp_c, CORR(pressure, humidity) AS corr_pressure_humidity FROM device_readings GROUP BY 1, 2, 3 HAVING corr_pressure_humidity > 0 ORDER BY temp_c_tier DESC NULLS LAST
